CREATE TABLE IF NOT EXISTS purchase_return_execution (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '采购退仓仓库执行ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '业务CGT退仓单ID',sequence_no INT NOT NULL COMMENT '当前业务单第几次仓库执行',execution_sn VARCHAR(50) NOT NULL COMMENT '奇门出库单号，业务CGT单号加执行序号',
 connection_id BIGINT NULL COMMENT '原仓库连接ID，虚拟执行为空',outbound_mode TINYINT NOT NULL COMMENT '1真实仓库出库、2自动虚拟出库',route_json JSON NOT NULL COMMENT '不可变仓库货主映射，不含密钥',payload_json JSON NOT NULL COMMENT '本次固定出库计划及收件信息',
 state VARCHAR(24) NOT NULL DEFAULT 'ACTIVE' COMMENT 'ACTIVE执行中、ENDED仓库最终结束、STOPPED原仓确认停止',dispatch_state VARCHAR(24) NOT NULL DEFAULT 'UNSENT' COMMENT 'UNSENT未发送、PENDING待发送、SENDING发送中、ACCEPTED已受理、UNKNOWN结果待确认、FAILED明确失败、CANCELED已停止、VIRTUAL虚拟执行',cancel_state VARCHAR(16) NOT NULL DEFAULT 'NONE' COMMENT 'NONE无停止、PENDING等待停止、UNKNOWN停止结果不明、CONFIRMED仓库确认停止',external_order VARCHAR(128) NOT NULL DEFAULT '' COMMENT '原仓库执行单号',
 quantity_mode VARCHAR(16) NOT NULL DEFAULT 'INCREMENTAL' COMMENT '审核快照，INCREMENTAL本次增量、CUMULATIVE带版本累计快照',fragment_mode VARCHAR(16) NOT NULL DEFAULT 'COMPLETE' COMMENT '审核快照，COMPLETE完整回传、SPLIT允许同消息明细分片',snapshot_version BIGINT NOT NULL DEFAULT 0 COMMENT '最近接受的累计快照顺序版本',
 hold_action VARCHAR(16) NOT NULL DEFAULT 'EXISTING' COMMENT 'INITIAL首次占用、EXISTING沿用余量、REHOLD恢复已释放余量',hold_json JSON NOT NULL COMMENT '固定库存占用或恢复请求，失败沿原身份重试',stock_ready TINYINT NOT NULL DEFAULT 0 COMMENT '本次执行的库存占用已确认',
 quantity BIGINT NOT NULL COMMENT '本次执行计划数量，单位见原行',accepted_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '本执行已确认实际出库',posted_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '本执行库存已扣账',receipt_final TINYINT NOT NULL DEFAULT 0 COMMENT '仅本执行的仓库最终确认，短出不等于业务全部完成',review_pending TINYINT NOT NULL DEFAULT 0 COMMENT '已绑定身份的回传数量冲突待核对',
 carrier_code VARCHAR(64) NOT NULL DEFAULT '' COMMENT '仓库回传头部快递编码',waybill VARCHAR(128) NOT NULL DEFAULT '' COMMENT '头部运单信息，不推断物理包裹数量',last_error VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '当前执行异常',created_by VARCHAR(64) NOT NULL COMMENT '本执行申请或审核人',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
 UNIQUE KEY company_sn(company_code,execution_sn) COMMENT '仓库执行身份唯一',UNIQUE KEY execution_sequence(company_code,return_id,sequence_no) COMMENT '同业务并发不重复追加执行',KEY original_execution(company_code,return_id,state,id) COMMENT '原业务执行分页与未结束执行检查',KEY connection_used(company_code,connection_id,id) COMMENT '已使用的连接映射不可变更'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='同一CGT多次仓库执行，各自停止和最终确认，不新建业务CGT';
CREATE TABLE IF NOT EXISTS purchase_return_execution_line (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '仓库执行商品行ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',execution_id BIGINT NOT NULL COMMENT '仓库执行ID',return_line_id BIGINT NOT NULL COMMENT '原采购退仓来源行ID，库存来源不改写',quantity BIGINT NOT NULL COMMENT '分配给本执行的数量',accepted_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '本执行原行已确认出库',posted_quantity BIGINT NOT NULL DEFAULT 0 COMMENT '本执行原行已扣账',supplier_accepted BIGINT NOT NULL DEFAULT 0 COMMENT '供应商已确认接受商品',supplier_refused BIGINT NOT NULL DEFAULT 0 COMMENT '供应商已确认拒收商品',
 UNIQUE KEY original_line(company_code,execution_id,return_line_id) COMMENT '同执行原行只分配一次',KEY parent_lines(company_code,return_id,id) COMMENT '当前页业务批量汇总',KEY source_line(company_code,return_line_id,execution_id) COMMENT '原来源累计执行追溯'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='仓库任务额度及实出，合计不得超过CGT原计划';
CREATE TABLE IF NOT EXISTS purchase_return_execution_request (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '继续或恢复申请ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '当前CGT业务ID',from_execution_id BIGINT NOT NULL COMMENT '本次申请前最后执行ID',kind VARCHAR(16) NOT NULL COMMENT 'CONTINUE沿用未出占用、RESTORE重新审核已释放余量',request_key VARCHAR(64) NOT NULL COMMENT '操作幂等请求键',request_hash CHAR(64) NOT NULL COMMENT '不可变申请摘要',state VARCHAR(24) NOT NULL COMMENT 'WAIT_STOP确认原仓结束、REVIEW恢复待审核、CREATED已追加执行、REJECTED已驳回',execution_id BIGINT NULL COMMENT '本次追加的仓库执行ID',reason VARCHAR(1000) NOT NULL COMMENT '继续或恢复原因',actor VARCHAR(64) NOT NULL COMMENT '申请人',reviewed_by VARCHAR(64) NOT NULL DEFAULT '' COMMENT '恢复审核人',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '申请时间',
 UNIQUE KEY request_once(company_code,request_key) COMMENT '重复点击不重复追加任务',UNIQUE KEY source_once(company_code,return_id,from_execution_id,kind) COMMENT '同一轮余量只生成一份申请',KEY parent_request(company_code,return_id,state,id) COMMENT '待继续或恢复审核扫描'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='当前CGT内继续及恢复申请，原占用有效时保持占用';
CREATE TABLE IF NOT EXISTS purchase_return_message (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '仓库回传组装消息ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',execution_id BIGINT NOT NULL COMMENT '原仓库执行ID',message_id VARCHAR(128) NOT NULL COMMENT '仓库outBizCode',header_hash CHAR(64) NOT NULL COMMENT '同消息各分片必须一致的原单状态及版本摘要',expected_lines INT NOT NULL COMMENT '声明本消息商品行数，非整个CGT计划行数',state VARCHAR(16) NOT NULL DEFAULT 'ASSEMBLING' COMMENT 'ASSEMBLING分片未完整、ACCEPTED已形成不可变出库事件、IGNORED旧累计版本',payload_hash CHAR(64) NOT NULL DEFAULT '' COMMENT '完整组装后的规范业务摘要',payload_json JSON NULL COMMENT '规范后的完整原行及包裹事实',part_count INT NOT NULL DEFAULT 0 COMMENT '已接收不同分片数，上限200',byte_count BIGINT NOT NULL DEFAULT 0 COMMENT '已接收规范分片字节，上限4MB',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次接收时间',
 UNIQUE KEY original_message(company_code,execution_id,message_id) COMMENT '跨执行的相同仓库消息号互不冲突',KEY pending_message(company_code,return_id,state,id) COMMENT '原业务未完整回传检查'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='区分分次出库与同消息报文分片，明细完整才确认出库';
CREATE TABLE IF NOT EXISTS purchase_return_message_part (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '已验签分片ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',message_id BIGINT NOT NULL COMMENT '原组装消息ID',part_hash CHAR(64) NOT NULL COMMENT '规范分片摘要，重复分片不重复接收',payload_json JSON NOT NULL COMMENT '已绑定仓库原单的分片明细及包裹',source_log_id BIGINT NOT NULL COMMENT '原回传报文日志ID',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '收到时间',UNIQUE KEY same_part(company_code,message_id,part_hash) COMMENT '相同分片幂等',KEY original_parts(company_code,message_id,id) COMMENT '有界组装原消息'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购退仓分片原证据，明细冲突时不拼接扣库';
CREATE TABLE IF NOT EXISTS purchase_return_outbound_line (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '本次实际出库来源ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',execution_id BIGINT NOT NULL COMMENT '原仓库执行ID',event_id BIGINT NOT NULL COMMENT '已确认库存扣账事件ID',execution_line_id BIGINT NOT NULL COMMENT '原仓库任务行',return_line_id BIGINT NOT NULL COMMENT '原采购退仓来源行',quantity BIGINT NOT NULL COMMENT '本次实际出库增量，按原批次质量成本',posted TINYINT NOT NULL DEFAULT 0 COMMENT '库存已成功扣账',UNIQUE KEY event_line(company_code,event_id,execution_line_id) COMMENT '同消息同原行只入账一次',KEY source_trace(company_code,return_id,return_line_id,id) COMMENT '包裹收货及成本来源追溯'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='规范化出库事实，库存只按此增量扣减，包裹不重复扣库';
CREATE TABLE IF NOT EXISTS purchase_return_parcel (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '已识别物理包裹ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',execution_id BIGINT NOT NULL COMMENT '原仓库执行ID',package_code VARCHAR(128) NOT NULL COMMENT '仓库明确提供的包裹号，不使用运单推断包裹数',carrier_code VARCHAR(64) NOT NULL DEFAULT '' COMMENT '本包裹实际快递编码',carrier_name VARCHAR(100) NOT NULL DEFAULT '' COMMENT '本包裹实际快递名称',waybill VARCHAR(128) NOT NULL DEFAULT '' COMMENT '本包裹实际运单号',content_hash CHAR(64) NOT NULL COMMENT '包裹商品事实摘要，变化须独立核对',content_state VARCHAR(24) NOT NULL DEFAULT 'PENDING' COMMENT 'PENDING内容未补全、MAPPED原行归属完整、REVIEW原行归属待核对、CONFLICT包裹事实冲突',evidence VARCHAR(1000) NOT NULL DEFAULT '' COMMENT '包裹补齐或原行人工核对依据',control_version BIGINT NOT NULL DEFAULT 1 COMMENT '人工补齐版本',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '首次回传时间',
 UNIQUE KEY original_package(company_code,execution_id,package_code) COMMENT '同执行包裹去重，运单号相同不合并包裹',KEY parent_parcel(company_code,return_id,content_state,id) COMMENT '包裹分页及待核对汇总'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='采购退仓物理包裹，与物流票及库存出库分别管理';
CREATE TABLE IF NOT EXISTS purchase_return_parcel_item (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '仓库包裹商品事实ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',parcel_id BIGINT NOT NULL COMMENT '物理包裹ID',item_no INT NOT NULL COMMENT '本包裹原商品序号',sku_sn VARCHAR(128) NOT NULL COMMENT '仓库回传SKU',quantity BIGINT NOT NULL COMMENT '本包裹该SKU数量',hint_line_id BIGINT NULL COMMENT '仓库明确提供的原执行行，可缺失',hint_batch VARCHAR(128) NOT NULL DEFAULT '' COMMENT '仓库明确提供的批次，可缺失',hint_grade VARCHAR(2) NOT NULL DEFAULT '' COMMENT '仓库明确提供的正次品，可缺失',
 UNIQUE KEY original_item(company_code,parcel_id,item_no) COMMENT '包裹原内容不重复登记',KEY parent_item(company_code,return_id,parcel_id,id) COMMENT '当前页批量包裹商品读取'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='原始包裹商品数量，不猜测库存来源或批次';
CREATE TABLE IF NOT EXISTS purchase_return_parcel_allocation (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '包裹商品原行归属ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',parcel_item_id BIGINT NOT NULL COMMENT '原包裹商品事实ID',execution_line_id BIGINT NOT NULL COMMENT '明确归属的仓库执行行',return_line_id BIGINT NOT NULL COMMENT '明确归属的原采购退仓行',quantity BIGINT NOT NULL COMMENT '明确分配的包裹商品数量',actor VARCHAR(64) NOT NULL COMMENT '唯一来源自动关联或人工核对人',evidence VARCHAR(1000) NOT NULL COMMENT '关联依据',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '关联时间',
 UNIQUE KEY original_assignment(company_code,parcel_item_id,execution_line_id) COMMENT '同包裹商品同原行只关联一次',KEY execution_quota(company_code,execution_line_id,id) COMMENT '包裹累计不得超过原行实际出库',KEY parent_assignment(company_code,return_id,id) COMMENT '供应商可收货来源'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='包裹商品与原批次成本的明确关联，补关联不重复扣库存';
CREATE TABLE IF NOT EXISTS purchase_return_event_parcel (
 company_code VARCHAR(64) NOT NULL COMMENT '所属公司',event_id BIGINT NOT NULL COMMENT '原出库回传事件',parcel_id BIGINT NOT NULL COMMENT '原仓库包裹ID',PRIMARY KEY(company_code,event_id,parcel_id) COMMENT '同包裹重复出现仍保留各次回传关联'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='出库消息与已识别包裹的多对多原证据';
CREATE TABLE IF NOT EXISTS purchase_return_supplier_line (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '供应商实际收货或拒收来源ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',receipt_id BIGINT NOT NULL COMMENT '原供应商收货凭证',execution_line_id BIGINT NOT NULL COMMENT '已扣账仓库执行行',return_line_id BIGINT NOT NULL COMMENT '原采购退仓来源行',decision VARCHAR(8) NOT NULL COMMENT 'ACCEPT实际接受、REFUSE拒收、SHORT短收证据',quantity BIGINT NOT NULL COMMENT '本次事实数量，短收不消耗接受拒收余额',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '登记时间',KEY parent_source(company_code,return_id,decision,id) COMMENT '原拒收可收回来源',KEY execution_receipt(company_code,execution_line_id,decision,id) COMMENT '供应商确认不得超过本执行已扣账量'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商收货规范来源，物流签收不自动确认商品接受';
CREATE TABLE IF NOT EXISTS purchase_return_supplier_parcel (
 id BIGINT AUTO_INCREMENT PRIMARY KEY COMMENT '收货事实绑定包裹关联ID',company_code VARCHAR(64) NOT NULL COMMENT '所属公司',supplier_line_id BIGINT NOT NULL COMMENT '原供应商收货或拒收事实ID',allocation_id BIGINT NOT NULL COMMENT '原包裹商品归属ID',quantity BIGINT NOT NULL COMMENT '该事实明确归属本包裹的数量',request_key VARCHAR(64) NOT NULL COMMENT '补绑定请求身份',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '绑定时间',UNIQUE KEY same_binding(company_code,supplier_line_id,allocation_id) COMMENT '补绑定不重复登记接受拒收',KEY parcel_receipt(company_code,allocation_id,supplier_line_id) COMMENT '包裹商品剩余可确认数量'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='供应商收货事实后补包裹关联，不重复确认或增加收回额度';
CREATE TABLE IF NOT EXISTS purchase_return_metadata_command (
 company_code VARCHAR(64) NOT NULL COMMENT '所属公司',return_id BIGINT NOT NULL COMMENT '原CGT业务ID',request_key VARCHAR(64) NOT NULL COMMENT '补齐关联幂等请求键',request_hash CHAR(64) NOT NULL COMMENT '不可变请求摘要',action VARCHAR(32) NOT NULL COMMENT '补包裹、关联原行或供应商事实绑定',payload_json JSON NULL COMMENT '本次独立补录或关联原请求，保留每次分量与证据；旧保留记录为空',create_time DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '操作时间',PRIMARY KEY(company_code,return_id,request_key) COMMENT '人工补齐只生效一次'
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='物流补齐和商品来源核对独立幂等，不能伪装出库消息';
